#include <filesystem>
#include <iostream>
#include <string_view>
#include <vector>

#include "filehash.h"
#include "merkle.h"

namespace {

void print_usage() {
    std::cerr << "Usage: branchaudit --version\n"
                 "       branchaudit hash <file>\n"
                 "       branchaudit root [<file>...]\n";
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << "branchaudit 0.1.0\n";
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
        // hash 恰好接受一个文件；缺失或多给都属于用法错误。
        if (argc != 3) {
            print_usage();
            return 2;
        }
        const branchaudit::FileHashResult result =
            branchaudit::sha256_file(argv[2]);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "root") {
        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
        std::vector<std::filesystem::path> paths;
        paths.reserve(static_cast<std::size_t>(argc - 2));
        for (int i = 2; i < argc; ++i) {
            paths.emplace_back(argv[i]);
        }
        const branchaudit::FileHashResult result =
            branchaudit::merkle_root_files(paths);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    print_usage();
    return 2;
}

#pragma once

// branchaudit 内部共享头（非公开 API）：普通文件摘要（hash）与 Merkle 文件
// 叶子（root）通过这里共用同一套文件定位、打开、流式分块读取与读取失败
// 处理，保证两种计算对同一文件遵守一致规则，也避免同一种文件错误需要在
// 两处分别维护。对外公开的参数、结果类型与头文件仍保持 filehash.h /
// merkle.h 中已有的形态不变。

#include "filehash.h"

namespace branchaudit::internal {

// 流式计算 path 所指文件的 SHA-256 摘要。
//
// prefix_byte == nullptr：只对文件的全部原始字节计算标准 SHA-256（hash）。
// prefix_byte 指向单个字节：该字节在任何文件字节之前恰好参与一次摘要
// （Merkle 叶子的 0x00 前缀）——即使文件为空它也存在，且不会随读取分块
// 重复加入。两种情况下都只对实际读取到的字节计算：不包含路径文字，不做
// 编码转换、换行替换或空白处理。
//
// 路径不存在、指向目录、无法打开或中途读取失败时，返回 error 非空的结果，
// 已读到的部分内容不会成为成功结果。固定缓冲流式读取，内存占用与文件长度无关。
FileHashResult sha256_file_digest(const std::filesystem::path& path,
                                  const unsigned char* prefix_byte);

}  // namespace branchaudit::internal

#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <vector>

#include "filehash.h"
#include "sha256.h"

namespace branchaudit {

// 32 字节原始摘要。Merkle 各层组合一律使用原始字节，不使用十六进制文本。
using Digest = std::array<std::uint8_t, Sha256::kDigestSize>;

// 空批次根：SHA-256 对空字节序列。
// 注意它与“单个空文件”的叶子摘要不同（叶子带 0x00 前缀）。
Digest merkle_empty_root();

// 文件叶子：SHA-256(0x00 || data)。
// 0x00 是值为 0x00 的单个原始前缀字节，不是字符串；data 为文件全部原始字节。
// 供已知字节内容时直接组合使用；文件请用流式的 merkle_root_files。
Digest merkle_leaf(const unsigned char* data, std::size_t size);

// 父摘要：SHA-256(0x01 || left || right)。
// 0x01 是值为 0x01 的单个原始前缀字节，left/right 各为 32 个原始字节，
// 先左后右，顺序不可交换。
Digest merkle_parent(const Digest& left, const Digest& right);

// 计算一个有序文件批次的 Merkle 根。
//
// 位置顺序完全取自 paths 的下标：不按文件名或摘要排序，也不去重；
// 同一路径重复出现、多个文件内容相同，都各自保留独立位置。根只反映各位置
// 的文件内容，不包含任何路径文字。
//
// 配对规则：每层相邻节点先左后右两两配对；若该层节点数为奇数，最后一个
// 节点没有伙伴，其摘要原样提升到上一层，不复制、不补零，直到只剩一个根。
// 只有一个文件时根即其叶子摘要；paths 为空时返回 merkle_empty_root()。
//
// 叶子按流式计算（固定缓冲），内存占用与文件大小无关。任一文件不存在、
// 指向目录、无法打开或读取失败时，整次计算失败：返回 error 非空的结果，
// 说明失败的路径和原因，不用其余文件产出部分结果。不打印、不退出进程。
FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths);

}  // namespace branchaudit

