toolUseResult.originalFile:
// 测试专用：在测试自身安排的条件下稳定制造两类真实文件访问错误，
// 不依赖碰巧出现的磁盘故障，也不需要 root。
//
//  1. 文件确实存在却无法打开：AF_UNIX 套接字路径。套接字在文件系统中
//     有名字（不是缺失路径），但用 open(2)/fopen 以普通文件方式打开必然
//     失败（Linux 上为 ENXIO）。
//
//  2. 文件已成功打开、已经读到部分内容后，后续读取出错：伪终端从端。
//     主端先写入一段数据并持有写端；等数据确实被读侧消费后，再关闭写端
//     与主端，使读侧下一次 read(2) 以 EIO 失败。已读到的部分字节必须被
//     文件计算丢弃，不能被当作正常 EOF 或部分成功。
//
// 这些机制只在本仓库的回归测试中使用，不属于公开 API；仅在 Linux/glibc
// 风格系统上可用，在其他平台上编译为可探测的空实现（supported() 为假），
// 测试据此跳过，而不是把“无法触发”算作通过。

#pragma once

#include <cerrno>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <filesystem>
#include <string>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <termios.h>
#include <thread>
#include <unistd.h>
#include <utility>

#include <pty.h>

namespace fault_fixture {

namespace fs = std::filesystem;

// 该平台是否支持两种故障机制。不支持时所有测试必须显式跳过并报告，
// 绝不能静默当作检查通过。
inline bool supported() {
#ifdef __linux__
    return true;
#else
    return false;
#endif
}

// ---- 故障一：存在但无法以普通文件方式打开 ---------------------------------

// 在 dir 下创建一个名为 name 的 AF_UNIX 套接字节点，返回其路径。
// 节点在文件系统中真实存在，但打开它做普通读必然失败。
struct UnopenableSocket {
    fs::path path;
    int fd = -1;
    bool ready = false;

    UnopenableSocket() = default;
    UnopenableSocket(const fs::path& dir, const std::string& name) {
        path = dir / name;
        fd = ::socket(AF_UNIX, SOCK_STREAM, 0);
        if (fd < 0) return;
        sockaddr_un addr{};
        addr.sun_family = AF_UNIX;
        const std::string p = path.string();
        // 留一个字节给 sun_path 的结尾 NUL。
        if (p.size() >= sizeof(addr.sun_path)) {
            ::close(fd);
            fd = -1;
            return;
        }
        std::memcpy(addr.sun_path, p.data(), p.size());
        if (::bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) {
            ::close(fd);
            fd = -1;
            return;
        }
        // 确认节点确实在文件系统中，且它不是普通文件/目录/缺失路径。
        struct stat st{};
        if (::stat(path.c_str(), &st) != 0 || !S_ISSOCK(st.st_mode)) {
            ::close(fd);
            fd = -1;
            return;
        }
        ready = true;
    }

    UnopenableSocket(const UnopenableSocket&) = delete;
    UnopenableSocket& operator=(const UnopenableSocket&) = delete;

    ~UnopenableSocket() {
        if (fd >= 0) ::close(fd);
        if (ready) {
            std::error_code ec;
            fs::remove(path, ec);
        }
    }
};

// ---- 故障二：部分读取后读取失败 -------------------------------------------

// 伪终端从端故障文件。构造后 start() 会：
//   - 建立 raw 模式伪终端，从端路径即“可打开的文件”；
//   - 由传入的读取函数（在独立线程内执行真正的被测代码）打开并读取；
//   - 主端写入 partial；确认读侧真正消费后关闭全部写端与主端，
//     使读侧阻塞中的下一次 read(2) 得到 EIO。
//
// 关键同步点：必须等从端输入队列排空（TIOCINQ 为 0），再额外等待读侧
// 进入下一次读取，最后才挂断；否则排队数据可能在被消费前随挂断丢弃，
// 无法保证“已读到部分内容”这一前提。
class PartiallyReadablePty {
public:
    PartiallyReadablePty() = default;
    PartiallyReadablePty(const PartiallyReadablePty&) = delete;
    PartiallyReadablePty& operator=(const PartiallyReadablePty&) = delete;

    ~PartiallyReadablePty() {
        if (master_ >= 0) ::close(master_);
        if (writer_ >= 0) ::close(writer_);
        if (slave_ >= 0) ::close(slave_);
    }

    bool ready() const { return ready_; }
    const std::string& path() const { return name_; }
    // 仅在确认部分字节已被读侧真正消费（从端输入队列排空）后为真：
    // 这是“先读到内容、随后读出错”前提成立的证据。
    bool partial_delivered() const { return delivered_; }

    // reader: 在线程中运行的被测读取逻辑，参数为从端路径。
    template <class Fn>
    void start_then_fail_after_partial(const std::string& partial, Fn&& reader) {
        int master = -1;
        int slave = -1;
        if (openpty(&master, &slave, nullptr, nullptr, nullptr) != 0) return;
        master_ = master;
        slave_ = slave;

        // raw：关闭回显、规范模式与信号生成，保证写入字节原样到达，
        // 且小数据不会被行规程合并或改写。
        termios tio{};
        if (tcgetattr(slave_, &tio) != 0) return;
        cfmakeraw(&tio);
        tio.c_cc[VMIN] = 1;
        tio.c_cc[VTIME] = 0;
        if (tcsetattr(slave_, TCSANOW, &tio) != 0) return;
        if (tcsetattr(master_, TCSANOW, &tio) != 0) return;

        char buf[256];
        if (ttyname_r(slave_, buf, sizeof(buf)) != 0) return;
        name_ = buf;

        // 不再直接持有 openpty 给出的从端 fd：读取方将按路径自行打开，
        // 与真实“命令行给出一个路径”的使用方式一致。
        ::close(slave_);
        slave_ = -1;

        // 在读取方打开之前先持有一个写端：否则从端可能在读取方首次
        // read 前就表现为挂断。该写端在确认部分数据被消费后才关闭。
        writer_ = ::open(name_.c_str(), O_WRONLY | O_NOCTTY);
        if (writer_ < 0) return;
        ready_ = true;

        std::thread worker([&, fn = std::forward<Fn>(reader)]() mutable {
            fn(name_);
        });

        // 先把部分内容写入主端。写端仍被我们持有，数据会进入从端输入
        // 队列，等待读取方打开并取走。
        const char* data = partial.data();
        std::size_t remaining = partial.size();
        auto give_up = std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (remaining > 0) {
            ssize_t w = ::write(master_, data, remaining);
            if (w > 0) {
                data += w;
                remaining -= static_cast<std::size_t>(w);
                continue;
            }
            if (errno == EINTR) continue;
            ::close(writer_);
            writer_ = -1;
            ::close(master_);
            master_ = -1;
            worker.join();
            ready_ = false;
            return;
        }

        // 等待读取方真正取走全部部分内容（从端输入队列排空）。
        int queued = -1;
        bool drained = false;
        give_up = deadline();
        while (std::chrono::steady_clock::now() < give_up) {
            if (ioctl(master_, TIOCINQ, &queued) == 0 && queued == 0) {
                drained = true;
                delivered_ = true;
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(2));
        }
        if (!drained) {
            // 触发挂断以解除读取方阻塞，然后回收线程。
            ::close(writer_);
            writer_ = -1;
            ::close(master_);
            master_ = -1;
            worker.join();
            ready_ = false;
            return;
        }

        // 读取方已拿到部分字节；留出窗口让其进入下一次阻塞读取。
        std::this_thread::sleep_for(std::chrono::milliseconds(50));

        // 关闭写端与主端：从端下一次 read(2) 以 EIO 失败。
        ::close(writer_);
        writer_ = -1;
        ::close(master_);
        master_ = -1;

        worker.join();
    }

private:
    int master_ = -1;
    int slave_ = -1;
    int writer_ = -1;
    std::string name_;
    bool ready_ = false;
    bool delivered_ = false;
};

}  // namespace fault_fixture

