#include <cerrno>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <filesystem>
#include <string>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <termios.h>
#include <thread>
#include <unistd.h>
#include <utility>

#include <pty.h>

namespace fault_fixture {

namespace fs = std::filesystem;

// 该平台是否支持两种故障机制。不支持时所有测试必须显式跳过并报告，
// 绝不能静默当作检查通过。
inline bool supported() {
#ifdef __linux__
    return true;
#else
    return false;
#endif
}

// ---- 故障一：存在但无法以普通文件方式打开 ---------------------------------

// 在 dir 下创建一个名为 name 的 AF_UNIX 套接字节点，返回其路径。
// 节点在文件系统中真实存在，但打开它做普通读必然失败。
