        tio.c_oflag = 0;
        tio.c_cflag = CS8 | CREAD;
        tio.c_lflag = ICANON;
        tio.c_cc[VMIN] = 1;
        tio.c_cc[VTIME] = 0;
        if (tcsetattr(slave, TCSANOW, &tio) != 0) return;
        if (tcsetattr(master_, TCSANOW, &tio) != 0) return;

