        if (writer_ >= 0) {
            ::close(writer_);
            writer_ = -1;
        }
        if (master_ >= 0) {
            ::close(master_);
            master_ = -1;
        }
        ready_ = false;
        return false;
    }

    void fail_after_thread_none() {
        ready_ = false;
    }

    int master_ = -1;
    int writer_ = -1;
    std::string name_;
    bool ready_ = false;
    bool delivered_ = false;
};

