    // 场景 B：有序批次。出错叶子在第二个位置，第一个位置的正常文件
    // 已先处理完；整次仍须失败，错误指向真正出错的文件。
    {
        fault_fixture::PartiallyReadablePty pty;
        branchaudit::FileHashResult batched;
        std::pair<std::string, std::string> cap_batch;
        pty.start_then_fail_after_line(
            body,
            [&](const std::string& p) {
                cap_batch = silent_root({good1, fs::path(p), good2}, &batched);
            });

        check(pty.ready(), "read-fault mid-batch: fixture opens a pty");
        check(pty.partial_delivered(),
              "read-fault mid-batch premise: partial bytes were read first");
        check(!batched.ok(),
              "read failure after good file: whole ordered batch fails");
        check(batched.error.find(pty.path()) != std::string::npos,
              "read failure mid-batch: error points at the real failing file");
        check(batched.error.find("read error") != std::string::npos,
              "read failure mid-batch: error states a read failure");
        // 不得输出：已处理文件单独的根、部分内容叶子的根、或跳过位置后的根。
        check(hex_of(batched.digest) != leaf_a,
              "read failure: no root of already-processed good file");
        check(hex_of(batched.digest) != root_a_partial,
              "read failure: no root using the failing file's partial content");
        check(hex_of(batched.digest) !=
                  hex_of(branchaudit::merkle_parent(leaf_bytes(bytes_of("a")),
                                       leaf_bytes(bytes_of("abc")))),
              "read failure: no root that skips the bad position");
        check(cap_batch.first.empty() && cap_batch.second.empty(),
              "read failure mid-batch: library does not print");
    }
}

