    cfmakeraw(&t); t.c_cc[VMIN]=1;t.c_cc[VTIME]=0;
    tcsetattr(s,TCSANOW,&t); tcsetattr(m,TCSANOW,&t);
    char nm[256]; ttyname_r(s,nm,sizeof nm); close(s);
    int w=open(nm,O_WRONLY|O_NOCTTY);
    const int N=8192;
    std::string payload(N,'\0'); for(int i=0;i<N;i++) payload[i]=(char)((i*31+7)&255);

    std::string got; std::thread rd([&]{
        std::ifstream in(nm,std::ios::binary);
        char b[65536];
        while(in){ in.read(b,sizeof b); auto c=in.gcount();
            if(c>0) got.append(b,c);
        }
        std::cerr<<"reader exit bad="<<in.bad()<<" got="<<got.size()<<"\n";
    });

    // nonblocking fill until EAGAIN
    int fl=fcntl(m,F_GETFL); fcntl(m,F_SETFL,fl|O_NONBLOCK);
    size_t off=0;
    while(off<payload.size()){
        ssize_t z=write(m,payload.data()+off,payload.size()-off);
        if(z>0){off+=z;continue;}
        if(errno==EAGAIN||errno==EWOULDBLOCK) break;
    }
    std::cerr<<"queued after fill: off="<<off<<"\n";
    fcntl(m,F_SETFL,fl); // back to blocking
    // blocking drain of remainder: each successful write proves reader consumed
    while(off<payload.size()){
        ssize_t z=write(m,payload.data()+off,payload.size()-off);
        if(z>0) off+=z;
    }
    std::cerr<<"all written off="<<off<<"\n";
    // now reads have started; wait queue drain reliably
    int q=-9;
    for(int i=0;i<5000;i++){ if(ioctl(w,TIOCINQ,&q)==0&&q==0)break; usleep(1000); }
    std::cerr<<"post-consume q="<<q<<" got(now)="<<got.size()<<"\n";
    usleep(50000);
    close(w); close(m); rd.join();
    std::cout<<"delivered="<<got.size()<<"\n";
    // digest of received via independent incremental sha (just report)
    branchaudit::Sha256 h; h.update((unsigned char*)got.data(),got.size());
    auto d=h.final(); char hx[65]; for(int i=0;i<32;i++) sprintf(hx+i*2,"%02x",d[i]);
    std::cout<<"plain="<<hx<<"\n";
    branchaudit::Sha256 h2; unsigned char z=0; h2.update(&z,1); h2.update((unsigned char*)got.data(),got.size());
    auto d2=h2.final(); for(int i=0;i<32;i++) sprintf(hx+i*2,"%02x",d2[i]);
    std::cout<<"leaf ="<<hx<<"\n";
}
