#include <unistd.h>
#include <utility>

#include <pty.h>

namespace fault_fixture {

namespace fs = std::filesystem;

// 该平台是否支持两种故障机制。不支持时所有测试必须显式跳过并报告，
// 绝不能静默当作检查通过。
inline bool supported() {
#ifdef __linux__
    return true;
#else
    return false;
#endif
}

// 固定的“部分内容”行体：100 个不含 CR/LF 的可打印 ASCII 字节（'!'..'`'）。
// 设施会追加唯一的换行符作为行结束，因此读取方实际拿到的部分内容是
// 行体 + '\n'（共 101 字节）。期望值由独立的 Python hashlib/OpenSSL
// 对这 101 字节计算，不使用本项目代码生成。
inline std::string partial_line_body() {
    std::string s;
    s.reserve(100);
    for (int i = 0; i < 100; ++i) {
        s.push_back(static_cast<char>((i * 7 + 33) % 64 + 33));
    }
    return s;
}

// ---- 故障一：存在但无法以普通文件方式打开 ---------------------------------

// 在 dir 下创建一个名为 name 的 AF_UNIX 套接字节点，返回其路径。
// 节点在文件系统中真实存在，但打开它做普通读必然失败。
struct UnopenableSocket {
    fs::path path;
    int fd = -1;
    bool ready = false;

    UnopenableSocket() = default;
    UnopenableSocket(const fs::path& dir, const std::string& name) {
        path = dir / name;
        fd = ::socket(AF_UNIX, SOCK_STREAM, 0);
        if (fd < 0) return;
        sockaddr_un addr{};
        addr.sun_family = AF_UNIX;
        const std::string p = path.string();
        // 留一个字节给 sun_path 的结尾 NUL。
        if (p.size() >= sizeof(addr.sun_path)) {
            ::close(fd);
            fd = -1;
            return;
        }
        std::memcpy(addr.sun_path, p.data(), p.size());
        if (::bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) {
            ::close(fd);
            fd = -1;
            return;
        }
        // 确认节点确实在文件系统中，且它不是普通文件/目录/缺失路径。
        struct stat st{};
        if (::stat(path.c_str(), &st) != 0 || !S_ISSOCK(st.st_mode)) {
            ::close(fd);
            fd = -1;
            return;
        }
        ready = true;
    }

    UnopenableSocket(const UnopenableSocket&) = delete;
    UnopenableSocket& operator=(const UnopenableSocket&) = delete;

    ~UnopenableSocket() {
        if (fd >= 0) ::close(fd);
        if (ready) {
            std::error_code ec;
            fs::remove(path, ec);
        }
    }
};

// ---- 故障二：读到一段确定内容后读取失败 -----------------------------------

// 伪终端从端故障文件。用法：
//
//   PartiallyReadablePty pty;
//   pty.start_then_fail_after_line(line_body, [&](const std::string& p){
//       // 在独立线程内对路径 p 执行真正的被测读取；它会读到 line_body+'\n'
//       // 后阻塞，随后收到读取失败。
//   });
//
// line_body 不得含 CR/LF；设施负责追加唯一的换行符作为行结束。
class PartiallyReadablePty {
public:
    PartiallyReadablePty() = default;
    PartiallyReadablePty(const PartiallyReadablePty&) = delete;
    PartiallyReadablePty& operator=(const PartiallyReadablePty&) = delete;

    ~PartiallyReadablePty() {
        if (master_ >= 0) ::close(master_);
        if (writer_ >= 0) ::close(writer_);
    }

    bool ready() const { return ready_; }
    const std::string& path() const { return name_; }
    // 仅在确认整行已被读取方真正消费（队列计数从行长度变为 0）后为真：
    // 这是“先读到确定的一段内容、随后读出错”前提成立的证据。
    bool partial_delivered() const { return delivered_; }

    template <class Fn>
    void start_then_fail_after_line(const std::string& line_body, Fn&& reader) {
        const std::string line = line_body + '\n';

        int master = -1;
        int slave = -1;
        if (openpty(&master, &slave, nullptr, nullptr, nullptr) != 0) return;
        master_ = master;

        // 规范模式：一次 read 至多返回一行；关闭回显、信号生成与全部
        // 输出/输入加工，保证行字节（含换行符）原样到达，不被改写。
        termios tio{};
        if (tcgetattr(master_, &tio) != 0) return;
        tio.c_iflag = 0;
        tio.c_oflag = 0;
        tio.c_cflag = CS8 | CREAD;
        tio.c_lflag = ICANON;
        tio.c_cc[VMIN] = 1;
        tio.c_cc[VTIME] = 0;
        if (tcsetattr(slave, TCSANOW, &tio) != 0) return;
        if (tcsetattr(master_, TCSANOW, &tio) != 0) return;

        char buf[256];
        if (ttyname_r(slave, buf, sizeof(buf)) != 0) {
            ::close(slave);
            return;
        }
        name_ = buf;
        ::close(slave);  // 读取方按路径自行打开，与真实用法一致。

        // 持有一个从端写端：保证读取方首次 read 前不会提前挂断；该 fd 也
        // 用于查询从端输入队列计数。在确认整行被消费后才关闭。
        writer_ = ::open(name_.c_str(), O_WRONLY | O_NOCTTY);
        if (writer_ < 0) return;

        // 预先写入整行，并等待行规程将其完整装配（TIOCINQ == 行长度）。
        // 这发生在读取方启动之前，因此没有任何竞态。
        if (!write_all(line) ||
            !wait_queue(static_cast<int>(line.size()), true)) {
            return;
        }

        // 读取方启动：第一次 read 取走整行，随后阻塞在第二行。
        ready_ = true;
        std::thread worker([fn = std::forward<Fn>(reader), this]() mutable {
            fn(name_);
        });

        // 等待整行被消费（队列计数确定性地由行长度变为 0）。
        if (!wait_queue(0, false)) {
            worker.join();
            return;
        }
        delivered_ = true;

        // 留出窗口，确保读取方已进入第二行的阻塞读取。
        std::this_thread::sleep_for(std::chrono::milliseconds(50));

        // 关闭写端与主端：阻塞中的下一次 read(2) 以 EIO 失败。
        ::close(writer_);
        writer_ = -1;
        ::close(master_);
        master_ = -1;

        worker.join();
    }

private:
    static constexpr int kTimeoutMs = 5000;

    bool write_all(const std::string& data) {
        const char* p = data.data();
        std::size_t remaining = data.size();
        while (remaining > 0) {
            ssize_t w = ::write(master_, p, remaining);
            if (w > 0) {
                p += w;
                remaining -= static_cast<std::size_t>(w);
                continue;
            }
            if (errno == EINTR) continue;
            return false;
        }
        return true;
    }

    // 等待从端输入队列计数达到 target。equal_target=false 时等待变为 0。
    bool wait_queue(int target, bool equal_target) {
        int queued = -1;
        const auto give_up =
            std::chrono::steady_clock::now() + std::chrono::milliseconds(kTimeoutMs);
        while (std::chrono::steady_clock::now() < give_up) {
            if (ioctl(writer_, TIOCINQ, &queued) == 0) {
                const bool hit = equal_target ? (queued == target) : (queued == 0);
                if (hit) return true;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        // 超时：挂断以解除任何可能阻塞的读取方，然后放弃本次故障注入。
        if (writer_ >= 0) {
            ::close(writer_);
            writer_ = -1;
        }
        if (master_ >= 0) {
            ::close(master_);
            master_ = -1;
        }
        ready_ = false;
        return false;
    }

    int master_ = -1;
    int writer_ = -1;
    std::string name_;
    bool ready_ = false;
    bool delivered_ = false;
};

