std::size_t forced = 0;
const std::size_t want =
    std::min(kForcedBytes, payload.size() - filled);
const auto give_up =
    std::chrono::steady_clock::now() + std::chrono::seconds(5);
// 用带超时的 poll 等待可写：若读取方不真正读文件（例如仅伪造一个带
// 错误文字的结果），缓冲始终已满、POLLOUT 永不到达，这里会超时并
// 干净地判失败，而不是无限阻塞。
while (forced < want) {
    pollfd pfd{master_, POLLOUT, 0};
    const int pr = ::poll(&pfd, 1, 2000);
    if (pr < 0) {
        if (errno == EINTR) continue;
        break;
    }
    if (pr == 0 ||
        std::chrono::steady_clock::now() >= give_up ||
        !(pfd.revents & POLLOUT)) {
        break;
    }
    ssize_t w = ::write(master_, payload.data() + filled + forced,
                        want - forced);
    if (w > 0) {
        forced += static_cast<std::size_t>(w);
        continue;
    }
    if (errno == EINTR) continue;
    break;
}
forced_ = forced;
delivered_ = filled + forced;

if (forced != want) {
    // 挂断以解除任何真实阻塞的读取方，再回收线程；伪造读取方则早已
    // 返回，join 立即完成。
    ::close(writer_);
    writer_ = -1;
    ::close(master_);
    master_ = -1;
    worker.join();
    ready_ = false;
    return;
}

