inline constexpr std::size_t kPayloadSize = 96 * 1024;

// ---- 故障一：存在但无法以普通文件方式打开 ---------------------------------

// 在 dir 下创建一个名为 name 的 AF_UNIX 套接字节点，返回其路径。
// 节点在文件系统中真实存在，但打开它做普通读必然失败。
