        const int flags = fcntl(master_, F_GETFL);
        if (flags < 0 || fcntl(master_, F_SETFL, flags | O_NONBLOCK) != 0) return;
        std::size_t off = 0;
        bool hit_eagain = false;
        while (off < payload.size()) {
            ssize_t w = ::write(master_, payload.data() + off,
                                payload.size() - off);
            if (w > 0) {
                off += static_cast<std::size_t>(w);
                continue;
            }
            if (errno == EINTR) continue;
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                hit_eagain = true;
                break;
            }
            abort_run();
            return;
        }
        if (!hit_eagain) {
            // 缓冲未能被填满，无法用后续阻塞写证明消费发生；放弃本次注入。
            abort_run();
            return;
        }
        const std::size_t filled = off;

        // (b) 启动读取方。
        ready_ = true;
        std::thread worker([fn = std::forward<Fn>(reader), this]() mutable {
            fn(name_);
        });

        // (c) 切回阻塞写，再写 kForcedBytes：仅当读取方读走等量字节后返回。
        if (fcntl(master_, F_SETFL, flags) != 0) {
            worker.join();
            abort_run();
            return;
        }
        std::size_t forced = 0;
        const std::size_t want =
            std::min(kForcedBytes, payload.size() - filled);
        const auto give_up =
            std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (forced < want) {
            ssize_t w = ::write(master_, payload.data() + filled + forced,
                                want - forced);
            if (w > 0) {
                forced += static_cast<std::size_t>(w);
                continue;
            }
            if (errno == EINTR) continue;
            break;
        }
        forced_ = forced;
        delivered_ = filled + forced;

        if (forced != want) {
            worker.join();
            abort_run();
            return;
        }

        // (d) 此时读取确已发生，TIOCINQ 可信：等待残留队列排空，确保读取方
        // 已取走全部已送达字节并进入下一次阻塞读取。
        int queued = -1;
        bool drained = false;
        while (std::chrono::steady_clock::now() < give_up) {
            if (ioctl(writer_, TIOCINQ, &queued) == 0 && queued == 0) {
                drained = true;
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        if (!drained) {
            worker.join();
            abort_run();
            return;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(20));

        // 挂断：阻塞中的下一次 read(2) 以 EIO 失败。
        ::close(writer_);
        writer_ = -1;
        ::close(master_);
        master_ = -1;
        worker.join();
    }

private:
    void abort_run() {
        if (writer_ >= 0) {
            ::close(writer_);
            writer_ = -1;
        }
        if (master_ >= 0) {
            ::close(master_);
            master_ = -1;
        }
        ready_ = false;
    }

    int master_ = -1;
    int writer_ = -1;
    std::string name_;
    bool ready_ = false;
    std::size_t delivered_ = 0;
    std::size_t forced_ = 0;
};

