// 伪终端从端故障文件。用法：
//
//   PartiallyReadablePty pty;
//   pty.start_then_fail_after_real_bytes([&](const std::string& p){
//       // 在独立线程内对路径 p 执行真正的被测读取；它会读到确定的一段
//       // 真实字节后阻塞，随后收到读取失败。
//   });
