def _force_write_nonblock(fd: int, view: memoryview, n: int, timeout: float) -> int:
    """保持 fd 非阻塞，用带超时的 select 等待可写后写入至多 n 字节。

    只有对端真的读走字节、腾出缓冲才能写完；对端不读则超时返回已写量。
    全程非阻塞，不会卡在一次 write 上。"""
    total = 0
    deadline = time.monotonic() + timeout
    while total < n:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        rlist, _, _ = select.select([], [fd], [], min(0.5, remaining))
        if not rlist:
            continue
        try:
            w = os.write(fd, view[total:total + (n - total)])
        except BlockingIOError:
            continue
        except InterruptedError:
            continue
        except OSError:
            break
        if w <= 0:
            break
        total += w
    return total

