                if (pfd.revents & (POLLERR | POLLHUP | POLLNVAL)) break;
                continue;
            }
            ssize_t w = ::write(master_, payload.data() + filled + forced,
                                want - forced);
            if (w > 0) {
                forced += static_cast<std::size_t>(w);
                continue;
            }
            if (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            break;
        }
