            // 挂断以解除任何真实阻塞的读取方，再回收线程；伪造读取方则早已
            // 返回，join 立即完成。
            ::close(writer_);
            writer_ = -1;
            ::close(master_);
            master_ = -1;
            worker.join();
            ready_ = false;
            return;
        }

        // (d) 此时读取确已发生，TIOCINQ 可信：等待残留队列排空，确保读取方
        // 已取走全部已送达字节并进入下一次阻塞读取。
        int queued = -1;
        bool drained = false;
        while (std::chrono::steady_clock::now() < give_up) {
            if (ioctl(writer_, TIOCINQ, &queued) == 0 && queued == 0) {
                drained = true;
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        if (!drained) {
            ::close(writer_);
            writer_ = -1;
            ::close(master_);
            master_ = -1;
            worker.join();
            ready_ = false;
            return;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(20));

        // 挂断：阻塞中的下一次 read(2) 以 EIO 失败。
        ::close(writer_);
        writer_ = -1;
        ::close(master_);
        master_ = -1;
        worker.join();
    }

private:
    void abort_run() {
        if (writer_ >= 0) {
            ::close(writer_);
            writer_ = -1;
        }
        if (master_ >= 0) {
            ::close(master_);
            master_ = -1;
        }
        ready_ = false;
    }

    int master_ = -1;
    int writer_ = -1;
    std::string name_;
    bool ready_ = false;
    std::size_t delivered_ = 0;
    std::size_t forced_ = 0;
};

